// ClusterID implements device.Declaration: the cluster declared.
func (Declare) ClusterID() uint32 { return ClusterID }

// ClusterDeclaration implements device.Declaration: the declaration in
// the form the device kit applies it.
func (d Declare) ClusterDeclaration() spec.ClusterDeclaration {
	decl := spec.ClusterDeclaration{Cluster: ClusterID, Initial: d.Initial.AttributeValues(), Server: d.HostServer, Ports: d}
	if d.OnWrite != nil {
		decl.Attach = d.attach
	}
	decl.Elements.Commands = append(decl.Elements.Commands, d.Commands...)
	if d.HandleAddKeySet != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdAddKeySet)
		decl.Attach = d.attach
	}
	if d.HandleUpdateKeySet != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdUpdateKeySet)
		decl.Attach = d.attach
	}
	if d.HandleRemoveKeySet != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdRemoveKeySet)
		decl.Attach = d.attach
	}
	if d.HandleAddGroup != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdAddGroup)
		decl.Attach = d.attach
	}
	if d.HandleUpdateGroup != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdUpdateGroup)
		decl.Attach = d.attach
	}
	if d.HandleRemoveGroup != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdRemoveGroup)
		decl.Attach = d.attach
	}
	if d.HandleAddAdmin != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdAddAdmin)
		decl.Attach = d.attach
	}
	if d.HandleUpdateAdmin != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdUpdateAdmin)
		decl.Attach = d.attach
	}
	if d.HandleRemoveAdmin != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdRemoveAdmin)
		decl.Attach = d.attach
	}
	if d.HandleAddPendingNode != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdAddPendingNode)
		decl.Attach = d.attach
	}
	if d.HandleRefreshNode != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdRefreshNode)
		decl.Attach = d.attach
	}
	if d.HandleUpdateNode != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdUpdateNode)
		decl.Attach = d.attach
	}
	if d.HandleRemoveNode != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdRemoveNode)
		decl.Attach = d.attach
	}
	if d.HandleUpdateEndpointForNode != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdUpdateEndpointForNode)
		decl.Attach = d.attach
	}
	if d.HandleAddGroupIdToEndpointForNode != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdAddGroupIdToEndpointForNode)
		decl.Attach = d.attach
	}
	if d.HandleRemoveGroupIdFromEndpointForNode != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdRemoveGroupIdFromEndpointForNode)
		decl.Attach = d.attach
	}
	if d.HandleAddBindingToEndpointForNode != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdAddBindingToEndpointForNode)
		decl.Attach = d.attach
	}
	if d.HandleRemoveBindingFromEndpointForNode != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdRemoveBindingFromEndpointForNode)
		decl.Attach = d.attach
	}
	if d.HandleAddAclToNode != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdAddAclToNode)
		decl.Attach = d.attach
	}
	if d.HandleRemoveAclFromNode != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdRemoveAclFromNode)
		decl.Attach = d.attach
	}
	return decl
}

// attach installs the declaration's veto and handlers on srv; the
// error names each one the server refused.
func (d Declare) attach(srv contract.ClusterServer) error {
	s := Wrap(srv)
	var errs []error
	if d.OnWrite != nil {
		errs = append(errs, spec.HookError(Name, "OnWrite", s.OnWrite(d.OnWrite)))
	}
	if d.HandleAddKeySet != nil {
		errs = append(errs, spec.HookError(Name, "HandleAddKeySet", s.HandleAddKeySet(d.HandleAddKeySet)))
	}
	if d.HandleUpdateKeySet != nil {
		errs = append(errs, spec.HookError(Name, "HandleUpdateKeySet", s.HandleUpdateKeySet(d.HandleUpdateKeySet)))
	}
	if d.HandleRemoveKeySet != nil {
		errs = append(errs, spec.HookError(Name, "HandleRemoveKeySet", s.HandleRemoveKeySet(d.HandleRemoveKeySet)))
	}
	if d.HandleAddGroup != nil {
		errs = append(errs, spec.HookError(Name, "HandleAddGroup", s.HandleAddGroup(d.HandleAddGroup)))
	}
	if d.HandleUpdateGroup != nil {
		errs = append(errs, spec.HookError(Name, "HandleUpdateGroup", s.HandleUpdateGroup(d.HandleUpdateGroup)))
	}
	if d.HandleRemoveGroup != nil {
		errs = append(errs, spec.HookError(Name, "HandleRemoveGroup", s.HandleRemoveGroup(d.HandleRemoveGroup)))
	}
	if d.HandleAddAdmin != nil {
		errs = append(errs, spec.HookError(Name, "HandleAddAdmin", s.HandleAddAdmin(d.HandleAddAdmin)))
	}
	if d.HandleUpdateAdmin != nil {
		errs = append(errs, spec.HookError(Name, "HandleUpdateAdmin", s.HandleUpdateAdmin(d.HandleUpdateAdmin)))
	}
	if d.HandleRemoveAdmin != nil {
		errs = append(errs, spec.HookError(Name, "HandleRemoveAdmin", s.HandleRemoveAdmin(d.HandleRemoveAdmin)))
	}
	if d.HandleAddPendingNode != nil {
		errs = append(errs, spec.HookError(Name, "HandleAddPendingNode", s.HandleAddPendingNode(d.HandleAddPendingNode)))
	}
	if d.HandleRefreshNode != nil {
		errs = append(errs, spec.HookError(Name, "HandleRefreshNode", s.HandleRefreshNode(d.HandleRefreshNode)))
	}
	if d.HandleUpdateNode != nil {
		errs = append(errs, spec.HookError(Name, "HandleUpdateNode", s.HandleUpdateNode(d.HandleUpdateNode)))
	}
	if d.HandleRemoveNode != nil {
		errs = append(errs, spec.HookError(Name, "HandleRemoveNode", s.HandleRemoveNode(d.HandleRemoveNode)))
	}
	if d.HandleUpdateEndpointForNode != nil {
		errs = append(errs, spec.HookError(Name, "HandleUpdateEndpointForNode", s.HandleUpdateEndpointForNode(d.HandleUpdateEndpointForNode)))
	}
	if d.HandleAddGroupIdToEndpointForNode != nil {
		errs = append(errs, spec.HookError(Name, "HandleAddGroupIdToEndpointForNode", s.HandleAddGroupIdToEndpointForNode(d.HandleAddGroupIdToEndpointForNode)))
	}
	if d.HandleRemoveGroupIdFromEndpointForNode != nil {
		errs = append(errs, spec.HookError(Name, "HandleRemoveGroupIdFromEndpointForNode", s.HandleRemoveGroupIdFromEndpointForNode(d.HandleRemoveGroupIdFromEndpointForNode)))
	}
	if d.HandleAddBindingToEndpointForNode != nil {
		errs = append(errs, spec.HookError(Name, "HandleAddBindingToEndpointForNode", s.HandleAddBindingToEndpointForNode(d.HandleAddBindingToEndpointForNode)))
	}
	if d.HandleRemoveBindingFromEndpointForNode != nil {
		errs = append(errs, spec.HookError(Name, "HandleRemoveBindingFromEndpointForNode", s.HandleRemoveBindingFromEndpointForNode(d.HandleRemoveBindingFromEndpointForNode)))
	}
	if d.HandleAddAclToNode != nil {
		errs = append(errs, spec.HookError(Name, "HandleAddAclToNode", s.HandleAddAclToNode(d.HandleAddAclToNode)))
	}
	if d.HandleRemoveAclFromNode != nil {
		errs = append(errs, spec.HookError(Name, "HandleRemoveAclFromNode", s.HandleRemoveAclFromNode(d.HandleRemoveAclFromNode)))
	}
	return errors.Join(errs...)
}
